$ErrorActionPreference = "Stop"

$root = (Get-Location).Path
$ws = Join-Path $root "runtime\workspaces\ahos-autopilot"
$pkg = Join-Path $ws "ahos_core"
$modulePath = Join-Path $pkg "ahos\opportunity_intake.py"
$testPath = Join-Path $pkg "tests\test_opportunity_intake.py"
$backlogPath = Join-Path $pkg "AHOS_BACKLOG.json"
$python = Join-Path $root ".venv\Scripts\python.exe"

if (-not (Test-Path $backlogPath)) { throw "AHOS_BACKLOG.json not found." }
if (-not (Test-Path $python)) { throw "Python venv not found: $python" }

$b = Get-Content $backlogPath -Raw | ConvertFrom-Json
if (-not ($b.tasks | Where-Object { $_.id -eq "AHOS-016" })) {
    $b.tasks += [pscustomobject]@{
        id = "AHOS-016"
        title = "Add read-only real-world opportunity intake adapters"
        status = "pending"
        risk = "low"
        authority = "B"
        requires_owner_approval = $false
        task = "Inside ahos_core only, add read-only public HTTP JSON/RSS opportunity intake adapters with explicit source configuration, stable candidate IDs, local persistence, and duplicate protection. No posting, outreach, login, payment, purchase, or other external side effects. Add focused tests using injected local fetchers so tests make no network calls."
    }
    [IO.File]::WriteAllText(
        $backlogPath,
        ($b | ConvertTo-Json -Depth 12),
        (New-Object System.Text.UTF8Encoding($false))
    )
}

[IO.File]::WriteAllBytes($modulePath, [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes($testPath, [Convert]::FromBase64String(""))

Write-Host "=== AHOS-016 LOCAL IMPLEMENTATION ==="
Write-Host "opportunity_intake.py + tests written."
Write-Host "Tests use injected local data; NO network and NO OpenAI API calls."

$oldPythonPath = $env:PYTHONPATH
Push-Location $pkg
try {
    $env:PYTHONPATH = $pkg
    & $python -m pytest -q
    $testExit = $LASTEXITCODE
} finally {
    Pop-Location
    $env:PYTHONPATH = $oldPythonPath
}

if ($testExit -ne 0) { throw "AHOS-016 tests failed." }

$b = Get-Content $backlogPath -Raw | ConvertFrom-Json
$t = $b.tasks | Where-Object { $_.id -eq "AHOS-016" } | Select-Object -First 1
$t.status = "completed"
if ($t.PSObject.Properties.Name -contains "completed_at") {
    $t.completed_at = [DateTime]::UtcNow.ToString("o")
} else {
    $t | Add-Member -NotePropertyName completed_at -NotePropertyValue ([DateTime]::UtcNow.ToString("o"))
}
[IO.File]::WriteAllText(
    $backlogPath,
    ($b | ConvertTo-Json -Depth 12),
    (New-Object System.Text.UTF8Encoding($false))
)

git -C $ws add ahos_core/ahos/opportunity_intake.py ahos_core/tests/test_opportunity_intake.py ahos_core/AHOS_BACKLOG.json
git -C $ws -c user.name="Miniverse Autopilot" -c user.email="miniverse@local.invalid" commit -m "feat(ahos): add read-only opportunity intake adapters"
if ($LASTEXITCODE -ne 0) { throw "git commit failed." }

git -C $ws push origin HEAD
if ($LASTEXITCODE -ne 0) { throw "git push failed." }

Write-Host ""
Write-Host "=== AHOS-016 COMPLETE ==="
Write-Host "Full AHOS tests: PASS"
Write-Host "Backlog: AHOS-016 -> completed"
Write-Host "Git push: PASS"
Write-Host "Network calls during tests: 0"
Write-Host "OpenAI API calls: 0"
